/**
 * Kit-managed. Generated by design4pro/agent-kit - edit the template there, never this copy.
 *
 * `agent-kit-check.mjs` is a merge gate: it is the first command of the validation gate and it
 * runs in CI's `verify` job. Its own hash half cannot cover it. A hand edit to the rendered script
 * is caught, because the lock's hash stops matching - but a bad *render* arrives together with a
 * lock that agrees with it, the hashes match, and the gate is quietly wrong while every check
 * stays green. That is the one failure mode this file exists for, and the only one nothing else
 * here would catch.
 *
 * So it asserts the exit-code contract the script's own header documents, and nothing else. The
 * logic belongs to the kit's `test/sync-check.mjs`; restating it here would only mean two places
 * to update and two places to disagree.
 *
 * Every case runs the real script against a throwaway repository under a temp directory. The
 * script derives its root from its own path (`dirname(import.meta.url)/../..`), so a copy at
 * `<fixture>/.ai/scripts/` judges the fixture and can never reach this repository's lock.
 */

import { execFileSync, spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import {
  chmodSync,
  cpSync,
  mkdirSync,
  mkdtempSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { afterEach, describe, expect, it } from 'vitest'

const SCRIPT = fileURLToPath(new URL('../agent-kit-check.mjs', import.meta.url))

const sha256 = (text) => createHash('sha256').update(text).digest('hex')

const MANAGED_BODY = 'kit\n'
const RENDERED = {
  'managed.txt': { sha256: sha256(MANAGED_BODY), mode: '100644' },
}
const lockAt = (kitVersion) => ({ kitVersion, rendered: RENDERED })

const fixtures = []
afterEach(() => {
  while (fixtures.length)
    rmSync(fixtures.pop(), { recursive: true, force: true })
})

function writeLock(root, lock) {
  writeFileSync(
    join(root, '.ai/agent-kit.lock.json'),
    typeof lock === 'string' ? lock : JSON.stringify(lock, null, 2),
  )
}

/**
 * A repository carrying the script, one managed file and a lock that matches it. `lock: null`
 * leaves the lock out entirely; a string is written verbatim, which is how malformed JSON is set
 * up.
 */
function repo({ files = { 'managed.txt': {} }, lock } = {}) {
  const root = mkdtempSync(join(tmpdir(), 'agent-kit-check-'))
  fixtures.push(root)
  mkdirSync(join(root, '.ai/scripts'), { recursive: true })
  cpSync(SCRIPT, join(root, '.ai/scripts/agent-kit-check.mjs'))

  const rendered = {}
  for (const [rel, spec] of Object.entries(files)) {
    const body = spec.body ?? MANAGED_BODY
    const mode = spec.mode ?? '100644'
    const abs = join(root, rel)
    mkdirSync(dirname(abs), { recursive: true })
    writeFileSync(abs, body)
    chmodSync(abs, mode.endsWith('755') ? 0o755 : 0o644)
    rendered[rel] = { sha256: sha256(body), mode }
  }

  if (lock !== null) writeLock(root, lock ?? { kitVersion: 7, rendered })
  return root
}

function run(root, ...args) {
  const { status, stdout, stderr } = spawnSync(
    process.execPath,
    [join(root, '.ai/scripts/agent-kit-check.mjs'), ...args],
    { encoding: 'utf8' },
  )
  return { code: status, out: stdout, err: stderr }
}

describe('the hash half', () => {
  it('exits 0 and says how many files it matched', () => {
    const { code, out } = run(repo())
    expect(code).toBe(0)
    expect(out).toContain('1 managed files match the lock (kit version 7)')
  })

  it('exits 1 naming the hand-edited file and the only remedy that works', () => {
    const root = repo()
    writeFileSync(join(root, 'managed.txt'), 'hand edited\n')
    const { code, err } = run(root)
    expect(code).toBe(1)
    expect(err).toContain('1 managed file(s) hand-edited')
    expect(err).toContain('managed.txt')
    expect(err).toContain('design4pro/agent-kit')
  })

  /**
   * Claude Code treats an unrunnable hook as no hook, in silence, so a lost executable bit
   * disarms the agent layer without failing anything. It is a `1` rather than a `2`: the file is
   * there, it is simply not armed.
   */
  it('exits 1 when a file the lock records as executable lost the bit', () => {
    const root = repo({
      files: { 'hook.sh': { body: '#!/bin/sh\n', mode: '100755' } },
    })
    chmodSync(join(root, 'hook.sh'), 0o644)
    const { code, err } = run(root)
    expect(code).toBe(1)
    expect(err).toContain('wrong executable bit')
    expect(err).toContain('want 100755')
  })

  it('checks the watched section too, so a moved skills lock is not silent', () => {
    const root = repo()
    writeFileSync(join(root, 'skills-lock.json'), 'moved\n')
    writeLock(root, {
      kitVersion: 7,
      rendered: RENDERED,
      watched: { 'skills-lock.json': { sha256: sha256('pinned\n') } },
    })
    const { code, err } = run(root)
    expect(code).toBe(1)
    expect(err).toContain('skills-lock.json')
  })

  // Missing is asked before edited, and the order is the message: "restore the file" and "stop
  // editing it" are different instructions, and a run told the second one first fixes neither.
  it('exits 2 for a missing file ahead of any hash complaint', () => {
    const root = repo({ files: { 'managed.txt': {}, 'gone.txt': {} } })
    rmSync(join(root, 'gone.txt'))
    writeFileSync(join(root, 'managed.txt'), 'hand edited\n')
    const { code, err } = run(root)
    expect(code).toBe(2)
    expect(err).toContain('managed file(s) missing')
    expect(err).toContain('gone.txt  (rendered)')
    expect(err).not.toContain('hand-edited')
  })

  it('exits 2 when the lock is missing', () => {
    const { code, err } = run(repo({ lock: null }))
    expect(code).toBe(2)
    expect(err).toContain('.ai/agent-kit.lock.json is missing')
  })

  it('exits 2 when the lock is not valid JSON', () => {
    const { code, err } = run(repo({ lock: '{ not json' }))
    expect(code).toBe(2)
    expect(err).toContain('not valid JSON')
  })

  it('exits 2 when the lock carries no rendered section', () => {
    const { code, err } = run(repo({ lock: { kitVersion: 7 } }))
    expect(code).toBe(2)
    expect(err).toContain('no `rendered` section')
  })
})

describe('argument parsing', () => {
  /**
   * The regression the script's header names: under an `indexOf`-only parser `--base=origin/x`
   * left BASE null, skipped the staleness half and exited 0 - a gate that exists and never fires.
   * A typo has to be as red as a real failure.
   */
  it('exits 2 on an argument it does not understand', () => {
    const { code, err } = run(repo(), '--bsae', 'origin/develop')
    expect(code).toBe(2)
    expect(err).toContain('unrecognised argument(s): --bsae origin/develop')
  })

  it.each([[['--base']], [['--base=']], [['--base', '--head', 'x']]])(
    'exits 2 on a --base that names no ref: %j',
    (args) => {
      const { code, err } = run(repo(), ...args)
      expect(code).toBe(2)
      expect(err).toContain('--base needs a git ref')
    },
  )

  it('exits 2 on --head without the --base it would be judged against', () => {
    const { code, err } = run(repo(), '--head', 'origin/pr-head')
    expect(code).toBe(2)
    expect(err).toContain('it needs --base')
  })
})

const git = (root, ...args) =>
  execFileSync('git', ['-C', root, ...args], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  })

/**
 * Three refs to compare against: `prehistory` carries no lock at all, `old` is kit 6 and `base` is
 * kit 7. The worktree is left level with `base`, and a case that wants a stale worktree rewrites
 * the lock itself - it is not in `rendered`, so doing that keeps the hash half clean.
 */
function historicRepo() {
  const root = repo()
  mkdirSync(join(root, '.githooks'))
  git(root, 'init', '-q', '-b', 'prehistory')
  git(root, 'config', 'user.email', 'kit@example.test')
  git(root, 'config', 'user.name', 'agent-kit fixture')
  git(root, 'config', 'commit.gpgsign', 'false')
  git(root, 'config', 'core.hooksPath', join(root, '.githooks'))

  rmSync(join(root, '.ai/agent-kit.lock.json'))
  git(root, 'add', '-A')
  git(root, 'commit', '-qm', 'before the kit')

  for (const [branch, version] of [
    ['old', 6],
    ['base', 7],
  ]) {
    git(root, 'checkout', '-qb', branch)
    writeLock(root, lockAt(version))
    git(root, 'add', '-A')
    git(root, 'commit', '-qm', `kit ${version}`)
  }
  return root
}

describe('the staleness half', () => {
  it('exits 0 when the branch is level with the base', () => {
    const { code, out } = run(historicRepo(), '--base', 'base')
    expect(code).toBe(0)
    expect(out).toContain('not behind base')
  })

  // Ahead is what a sync pull request looks like, so only behind may be a failure.
  it('exits 0 when the branch is ahead of the base', () => {
    expect(run(historicRepo(), '--base', 'old').code).toBe(0)
  })

  it("exits 3 when the branch's pipeline layer is older than the base's", () => {
    const root = historicRepo()
    writeLock(root, lockAt(6))
    const { code, err } = run(root, '--base', 'base')
    expect(code).toBe(3)
    expect(err).toContain('older than base')
    expect(err).toContain('git merge origin/<base>')
  })

  /**
   * The reason `--head` exists. On a `pull_request` event the checkout is `refs/pull/N/merge`, and
   * a three-way merge takes the base's side of the lock whenever the head never touched it - so
   * judging the worktree compares the base against itself and passes every stale branch. Both
   * directions are pinned, because a `--head` that is ignored would still pass the first row.
   */
  it('judges --head rather than the worktree', () => {
    const root = historicRepo()
    expect(run(root, '--base', 'base', '--head', 'old').code).toBe(3)
    expect(run(root, '--base', 'old', '--head', 'base').code).toBe(0)
  })

  it('exits 0 when the base predates the kit, because there is nothing to be behind', () => {
    const { code, out } = run(historicRepo(), '--base', 'prehistory')
    expect(code).toBe(0)
    expect(out).toContain('carries no lock')
  })

  it('exits 3 when the head predates the kit and the base does not', () => {
    const { code, err } = run(
      historicRepo(),
      '--base',
      'base',
      '--head',
      'prehistory',
    )
    expect(code).toBe(3)
    expect(err).toContain('predates the agent-kit adoption')
  })

  // A ref nobody fetched is a misconfigured workflow, and passing there is how a gate quietly
  // stops gating.
  it('exits 2 on a ref that does not resolve to a commit', () => {
    const { code, err } = run(historicRepo(), '--base', 'no-such-ref')
    expect(code).toBe(2)
    expect(err).toContain('does not resolve to a commit')
  })

  it('exits 2 when the two kit versions cannot be ordered', () => {
    const root = historicRepo()
    writeLock(root, lockAt('seven'))
    const { code, err } = run(root, '--base', 'base')
    expect(code).toBe(2)
    expect(err).toContain('kitVersion is not a number')
  })
})
